describe('Skip Navigation Links Accessibility', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.injectAxe();
  });

  it('should have skip navigation link as first focusable element on page load', () => {
    // Tab to first focusable element
    cy.get('body').tab();

    // Verify the first focused element is a skip navigation link
    cy.focused().should('have.attr', 'href').and('include', '#main');
    cy.focused().should('have.class', 'skip-link');
    cy.focused().should('contain', 'Skip to main content');
  });

  it('should make skip link visible and functional when focused', () => {
    // Initially skip link should be visually hidden
    cy.get('.skip-link')
      .should('have.css', 'position', 'absolute')
      .should('have.css', 'left', '-9999px');

    // Tab to skip link
    cy.get('body').tab();

    // When focused, skip link should become visible
    cy.focused()
      .should('have.class', 'skip-link')
      .should('be.visible');

    // Verify it has proper styling when focused
    cy.focused().should('have.css', 'left').and('not.equal', '-9999px');
  });

  it('should navigate to main content when skip link is activated', () => {
    // Tab to skip link
    cy.get('body').tab();

    // Verify focus is on skip link
    cy.focused().should('have.class', 'skip-link');

    // Press Enter to activate
    cy.focused().type('{enter}');

    // Verify focus moves to main content area
    cy.focused().should('have.attr', 'id', 'main');
  });

  it('should have skip link before navigation elements in tab order', () => {
    const focusedElements = [];

    // Collect first 3 focused elements
    for (let i = 0; i < 3; i++) {
      cy.get('body').tab();
      cy.focused().then(($el) => {
        focusedElements.push($el.attr('class'));
      });
    }

    // Verify skip-link is the first element
    cy.get('body').tab();
    cy.focused().should('have.class', 'skip-link');
  });

  it('should pass axe accessibility checks for skip navigation', () => {
    cy.checkA11y(null, {
      rules: {
        'skip-link': { enabled: true }
      }
    });
  });

  it('should handle multiple skip links for different sections', () => {
    // Verify multiple skip links exist if applicable
    cy.get('[href^="#"]').filter((index, el) => {
      return el.textContent.toLowerCase().includes('skip');
    }).should('have.length.at.least', 1);

    // Tab through and verify first is skip link
    cy.get('body').tab();
    cy.focused().should('have.attr', 'href').and('match', /^#(main|content)/);
  });

  it('should maintain skip link accessibility on page resize', () => {
    // Set initial viewport
    cy.viewport(1280, 720);

    cy.get('body').tab();
    cy.focused().should('have.class', 'skip-link');

    // Resize viewport
    cy.viewport(375, 667);

    // Reset focus and verify skip link is still first
    cy.get('body').focus();
    cy.get('body').tab();
    cy.focused().should('have.class', 'skip-link');
  });

  it('should not interfere with keyboard navigation after skip link activation', () => {
    // Activate skip link
    cy.get('body').tab();
    cy.focused().type('{enter}');

    // Verify we're at main content
    cy.focused().should('have.attr', 'id', 'main');

    // Continue tabbing should work normally
    cy.get('body').tab();
    cy.focused().should('not.have.class', 'skip-link');
  });
});
